import { storyCaption } from '@/components/visuals/dot-engine/story-caption';
import type { DotGrid } from '@/components/visuals/dot-engine/dot-morph-dots';
import type { StoryPicture } from '@/components/visuals/dot-engine/dot-story-beats';
import { cellsOfStates } from '@/components/visuals/dot-engine/dot-story-cells';

/** What the page-hero stories share: the hero monitor's 58 by 38 screen, and the caption column beside each picture. */

// The monitor's screen has no backdrop pattern to clear, so the dots need no halo of their own.
export const HERO_STORY_GRID: DotGrid = { columns: 58, rows: 38, pitch: 10, dotRadius: 3.2, ringStroke: 1, haloRadius: 0 };
const CAPTION_COLUMN = 34;

export const blankScreen = () => new Uint8Array(HERO_STORY_GRID.columns * HERO_STORY_GRID.rows);
export const pictureOfStates = (states: Uint8Array): StoryPicture => ({ states, cells: cellsOfStates(HERO_STORY_GRID, states) });
export const between = (value: number, from: number, to: number) => value >= from && value <= to;
export const cellAt = (column: number, row: number) => row * HERO_STORY_GRID.columns + column;
export const heroCaption = (label: string, value: string, detail: string) => storyCaption(HERO_STORY_GRID, CAPTION_COLUMN, label, value, detail);

/** Which step of a run a hold has reached: -1 before it starts, then 0 up to `last`. */
export const stepAt = (heldSeconds: number, { startsAt, everySeconds }: { startsAt: number; everySeconds: number }, last: number) => (heldSeconds < startsAt ? -1 : Math.min(last, Math.floor((heldSeconds - startsAt) / everySeconds)));

import { distanceToSegment, type DotShape, type GridPoint } from '@/components/visuals/dot-engine/dot-story-cells';

const LETTER = { widthOfHeight: 0.8, crossbarAt: 0.62, gapOfHeight: 0.16, bowlOfHeight: 0.3 };

/**
 * A type specimen, "Aa", `size` rows tall with its top-left corner at `origin`, drawn with strokes `weight` dots
 * either side of their line, so the same letters can be set light or bold.
 */
export function typeSpecimen(origin: GridPoint, size: number, weight: number): DotShape {
	const width = size * LETTER.widthOfHeight;
	const foot = origin.row + size;
	const apex = { column: origin.column + width / 2, row: origin.row };
	const crossbarRow = origin.row + size * LETTER.crossbarAt;
	const crossbarInset = (width / 2) * (1 - LETTER.crossbarAt);
	const strokes: GridPoint[][] = [
		[{ column: origin.column, row: foot }, apex],
		[apex, { column: origin.column + width, row: foot }],
		[
			{ column: origin.column + crossbarInset, row: crossbarRow },
			{ column: origin.column + width - crossbarInset, row: crossbarRow },
		],
	];
	const bowl = { column: origin.column + width + size * (LETTER.gapOfHeight + LETTER.bowlOfHeight), row: foot - size * LETTER.bowlOfHeight, radius: size * LETTER.bowlOfHeight };
	const stem = [
		{ column: bowl.column + bowl.radius, row: bowl.row - bowl.radius },
		{ column: bowl.column + bowl.radius, row: foot },
	];
	return (column, row) =>
		strokes.some(([from, to]) => distanceToSegment(column, row, from, to) <= weight) ||
		distanceToSegment(column, row, stem[0], stem[1]) <= weight ||
		Math.abs(Math.hypot(column - bowl.column, row - bowl.row) - bowl.radius) <= weight;
}

import { DOT_ABSENT, DOT_HOLLOW, type DotGrid } from '@/components/visuals/dot-engine/dot-morph-dots';
import type { StoryPicture } from '@/components/visuals/dot-engine/dot-story-beats';
import { cellsOfStates, paintShape, roundedBox, type DotBox } from '@/components/visuals/dot-engine/dot-story-cells';

const CORNER_RADIUS = 3;

/**
 * A wide field for something typed into a story. A field that is only a border has too little in it to melt into or
 * out of, so it comes in two pictures: `empty`, with room for the text, and `filled`, full of rings, which it arrives
 * and leaves as. `along` says how far along the field a dot is, so it can clear and refill from its left.
 */
export function promptField(grid: DotGrid, box: DotBox) {
	const picture = (isFilled: boolean): StoryPicture => {
		const states = paintShape(grid, new Uint8Array(grid.columns * grid.rows), roundedBox(box, CORNER_RADIUS), (column, row) =>
			isFilled || Math.min(column - box.left, box.right - column, row - box.top, box.bottom - row) <= 1 ? DOT_HOLLOW : DOT_ABSENT
		);
		return { states, cells: cellsOfStates(grid, states) };
	};
	return { empty: picture(false), filled: picture(true), along: (column: number) => Math.min(1, Math.max(0, (column - box.left) / (box.right - box.left))) };
}

import type { DotGrid } from '@/components/visuals/dot-engine/dot-morph-dots';
import { clamp01 } from '@/components/visuals/dot-engine/dot-story-cells';

const TEXT_FADE_SECONDS = 0.3;

export const NEVER = Number.POSITIVE_INFINITY;

export function revealSchedule({ columns, rows }: DotGrid, revealsAt: (column: number, row: number) => number) {
	const schedule = new Float32Array(columns * rows);
	for (let cell = 0; cell < schedule.length; cell++) schedule[cell] = revealsAt(cell % columns, Math.floor(cell / columns));
	return schedule;
}

export function paintRevealed(states: Uint8Array, revealed: Uint8Array, schedule: Float32Array, heldSeconds: number) {
	for (let cell = 0; cell < states.length; cell++) {
		if (heldSeconds >= schedule[cell]) states[cell] = revealed[cell];
	}
}

export const fadedInAt = (heldSeconds: number, startsAt: number) => clamp01((heldSeconds - startsAt) / TEXT_FADE_SECONDS);
